def battle_map(w,h,title,routes):
    b=f'<rect x="5" y="5" width="{w-10}" height="{h-10}" fill="#fff" stroke="#111" stroke-width="2"/>'+T(w/2,28,title,18,'middle',700)
    b+='<path d="M60 60 Q40 160 90 260 Q120 320 200 330" fill="none" stroke="#6a8" stroke-width="10"/><path d="M60 60 Q40 160 90 260 Q120 320 200 330" fill="none" stroke="#9bc" stroke-width="6"/>'
    b+='<polyline points="85,70 160,150 200,230 270,300" fill="none" stroke="#111" stroke-width="3" stroke-dasharray="8 4"/>'
    b+='<polyline points="120,60 190,140 260,230 310,285" fill="none" stroke="#111" stroke-width="3" stroke-dasharray="3 3"/>'
    b+='<ellipse cx="300" cy="170" rx="60" ry="45" fill="#e9e1c8" stroke="#555"/><ellipse cx="320" cy="260" rx="45" ry="35" fill="#e9e1c8" stroke="#555"/>'
    for i,(x,y,t) in enumerate(routes): b+=T(x,y,t,12,'middle',700)
    b+='<line x1="30" y1="360" x2="130" y2="360" stroke="#111" stroke-width="2"/>'+T(80,376,'میل',11,'middle',700)
    return svg(w,h,'Schematic plan of the Battle of Badr: the coastal strip, the route of the Muslim army, the route of the Quraysh army and the route of Abu Sufyan’s trade caravan',b)
